    s += '<text x="' + (xEnd - 4).toFixed(0) + '" y="' + (Y(pe.hist_ceiling) - 4).toFixed(0) + '" text-anchor="end" style="fill:var(--nino)">' + esc(pe.ceiling_label || 'record of the series') + ' ' + fnum(pe.hist_ceiling) + '</text>';
