    var s = svgOpen(W, H) + '<text class="tt" x="' + Lp + '" y="13">NOAA weekly indices, last ' + n + ' weeks, °C' + (RC ? '; right: the same four in the strongest past events, to the same week of the year' : '') + '</text>';
