        var last = v[v.length - 1], sorted = v.slice().sort(function (a, b) { return b - a; });
        var rank = sorted.indexOf(last) + 1, mx = sorted[0], mn = sorted[sorted.length - 1];
        var above = v.filter(function (x) { return x >= last; }).length;
